CREATE TRIGGER conversation_history_source_delete
                AFTER DELETE ON agent_session_context_messages BEGIN
                    DELETE FROM conversation_history_dirty WHERE session_id=OLD.session_id AND seq=OLD.seq;
                    DELETE FROM conversation_history_fts
                    WHERE rowid=(SELECT rowid FROM conversation_history_fts_map
                                 WHERE session_id=OLD.session_id AND seq=OLD.seq);
                    DELETE FROM conversation_history_fts_map
                    WHERE session_id=OLD.session_id AND seq=OLD.seq;
                    INSERT OR IGNORE INTO conversation_history_dirty(session_id,seq)
                    SELECT session_id,seq FROM agent_session_context_messages
                    WHERE session_id=OLD.session_id AND trace_id=OLD.trace_id AND role='agent';
                END

CREATE TRIGGER memory_fts_update AFTER UPDATE OF content,memory_type ON memory_entries
                    BEGIN
                        DELETE FROM memory_entries_fts WHERE memory_id=old.memory_id;
                        INSERT INTO memory_entries_fts(memory_id,content,memory_type)
                        VALUES(new.memory_id,new.content,new.memory_type);
                    END

CREATE TABLE manager_goal_matter_links (
                    goal_id TEXT PRIMARY KEY, manager_session_id TEXT NOT NULL, matter_id TEXT NOT NULL
                )

CREATE TABLE manager_queue_fairness (
                    manager_session_id TEXT PRIMARY KEY, last_served INTEGER NOT NULL
                )

CREATE TABLE manager_work_claims (
                    resource_key TEXT PRIMARY KEY, queue_id TEXT NOT NULL, run_id TEXT NOT NULL
                )

CREATE TABLE memory_projects(
                    project_id TEXT PRIMARY KEY, created_at TEXT NOT NULL
                )

CREATE TRIGGER conversation_semantic_new_session
                    AFTER INSERT ON agent_sessions BEGIN
                      INSERT OR IGNORE INTO conversation_semantic_state(session_id,fingerprint)
                      SELECT NEW.session_id,fingerprint FROM conversation_semantic_state
                      GROUP BY fingerprint;
                    END;
